      var all=new CheckBox{Text="Select All Microservices",AutoSize=true,Font=new(Font,FontStyle.Bold),Margin=new(6)}; all.Text="Select All"; all.CheckedChanged+=(_,_)=>{foreach(var c in selected.Values)c.Checked=all.Checked;};left.Controls.Add(all,0,0);
      var list=new TableLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,ColumnCount=3,Padding=new(8),GrowStyle=TableLayoutPanelGrowStyle.AddRows,CellBorderStyle=TableLayoutPanelCellBorderStyle.Single};list.ColumnStyles.Add(new(SizeType.Absolute,38));list.ColumnStyles.Add(new(SizeType.Percent,100));list.ColumnStyles.Add(new(SizeType.Absolute,190));
