      var uiCb=new CheckBox{AutoSize=true,Margin=new(4)}; selected["Angular UI"]=uiCb; var uiLabel=new Label{Text="Angular UI",AutoSize=true,Anchor=AnchorStyles.Left,Margin=new(4,8,4,4),Font=new(Font,FontStyle.Bold)}; var uiState=new Label{Text="NOT DEPLOYED",AutoSize=true,Anchor=AnchorStyles.Left,Margin=new(4,8,4,4)}; states["Angular UI"]=uiState; list.Controls.Add(uiCb); list.Controls.Add(uiLabel); list.Controls.Add(uiState);
